// An object that defines the blob inventory rule filter conditions. For 'Blob' definition.objectType all filter properties
// are applicable, 'blobTypes' is required and others are optional. For 'Container' definition.objectType only prefixMatch
// is applicable and is optional.
type BlobInventoryPolicyFilter struct {
	// BlobTypes: An array of predefined enum values. Valid values include blockBlob, appendBlob, pageBlob. Hns accounts does
	// not support pageBlobs. This field is required when definition.objectType property is set to 'Blob'.
	BlobTypes []string `json:"blobTypes,omitempty"`

	// CreationTime: This property is used to filter objects based on the object creation time
	CreationTime *BlobInventoryCreationTime `json:"creationTime,omitempty"`

	// ExcludePrefix: An array of strings with maximum 10 blob prefixes to be excluded from the inventory.
	ExcludePrefix []string `json:"excludePrefix,omitempty"`

	// IncludeBlobVersions: Includes blob versions in blob inventory when value is set to true. The definition.schemaFields
	// values 'VersionId and IsCurrentVersion' are required if this property is set to true, else they must be excluded.
	IncludeBlobVersions *bool `json:"includeBlobVersions,omitempty"`

	// IncludeDeleted: For 'Container' definition.objectType the definition.schemaFields must include 'Deleted, Version,
	// DeletedTime and RemainingRetentionDays'. For 'Blob' definition.objectType and HNS enabled storage accounts the
	// definition.schemaFields must include 'DeletionId, Deleted, DeletedTime and RemainingRetentionDays' and for Hns disabled
	// accounts the definition.schemaFields must include 'Deleted and RemainingRetentionDays', else it must be excluded.
	IncludeDeleted *bool `json:"includeDeleted,omitempty"`

	// IncludeSnapshots: Includes blob snapshots in blob inventory when value is set to true. The definition.schemaFields value
	// 'Snapshot' is required if this property is set to true, else it must be excluded.
	IncludeSnapshots *bool `json:"includeSnapshots,omitempty"`

	// PrefixMatch: An array of strings with maximum 10 blob prefixes to be included in the inventory.
	PrefixMatch []string `json:"prefixMatch,omitempty"`
}

